import {portraitSource} from './custom-portrait.js';
import {sceneAsset,eventLocation,SEASONS,seasonForMonth} from './scenery.js';
import {getPortrait,standingFile} from './engine.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const yearOf=month=>Math.floor((Math.max(1,Math.min(60,month))-1)/12)+1;
const monthLabel=month=>`${yearOf(month)}년 차 · ${(Math.max(1,Math.min(60,month))-1)%12+1}월`;
const typeLabel=row=>({month:'월간 기록',event:'선택의 순간',location:'사업장 변경',plan:'계획 기록',item:'운영 기록'}[row.type]||'기록');
export const importantRecord=row=>typeof row.choice==='string'&&!!row.choice.trim();
export function recordScene(state,data,row){
 const event=data.events.find(e=>e.id===row.eventId||e.title===row.title),who=row.who||event?.who||'mentor',person=data.story.cast.find(p=>p.id===who)||data.story.cast.find(p=>p.id==='mentor');
 const place=row.businessPlace||eventLocation({pending:{who}}),portrait=row.type==='event'&&person?person.file:standingFile(state.portrait);
 return `<div class="record-scene"><img class="record-backdrop" src="${sceneAsset(place,row.month)}" alt="${SEASONS[seasonForMonth(row.month)]}의 기록 장면" loading="lazy"><img class="record-person" src="${row.type==='event'?'assets/'+portrait:portraitSource(state,'assets/'+portrait)}" alt="${esc(row.type==='event'&&person?person.name:state.name+' 대표')}" loading="lazy"><span>${esc(typeLabel(row))}</span></div>`;
}
export function historyJournal(state,data,selectedYear='all'){
 const rows=(state.journal||[]).map((row,index)=>({...row,index})).filter(importantRecord).sort((a,b)=>a.month-b.month||b.index-a.index),years=[...new Set(rows.map(row=>yearOf(row.month)))].sort((a,b)=>a-b),current=years.at(-1);
 return `<section class="history-section" id="history-records"><div class="history-section-heading"><h2>선택의 타임라인</h2><button class="quiet" data-action="history-latest">최근 기록으로</button></div><div class="history-year-tabs" role="group" aria-label="기록 연차 선택"><button data-action="history-year" data-id="all" class="${selectedYear==='all'?'selected':''}" aria-pressed="${selectedYear==='all'}">전체</button>${years.map(year=>`<button data-action="history-year" data-id="${year}" class="${String(year)===String(selectedYear)?'selected':''}" aria-pressed="${String(year)===String(selectedYear)}">${year}년 차</button>`).join('')}</div><p class="history-replay-note">기록을 열어 당시의 선택을 다시 보거나, 저장된 시점부터 새 슬롯에서 다른 선택을 할 수 있어요.</p>${years.filter(year=>selectedYear==='all'||String(year)===String(selectedYear)).map(year=>{const entries=rows.filter(row=>yearOf(row.month)===year);return `<details class="history-year-group" id="history-year-${year}" ${selectedYear!=='all'||year===current?'open':''}><summary><span>${year}년 차</span><small>${entries.length}개의 기록 · 선택 ${entries.filter(row=>row.choice).length}번</small></summary><div class="history-entry-grid">${entries.map(row=>`<article class="card history-entry ${importantRecord(row)?'important':''}">${importantRecord(row)?recordScene(state,data,row):''}<div class="history-entry-content"><small>${monthLabel(row.month)} · ${typeLabel(row)}</small><h3>${esc(row.title)}</h3>${row.choice?`<p class="history-choice">${esc(row.choice)}</p>`:`<p>${esc(row.text)}</p>`}${row.adviser?`<small>따른 조언 · ${esc(row.adviser)}</small>`:''}<button class="quiet" data-action="history-record" data-index="${row.index}">${importantRecord(row)?'장면 다시 보기':'기록 열기'}</button></div></article>`).join('')}</div></details>`;}).join('')||'<div class="empty-state"><strong>선택을 마치면 이곳에 기록돼요.</strong></div>'}</section>`;
}
export function historyRecord(state,data,index){
 const row=state.journal?.[index];if(!row||!importantRecord(row))return null;const indexes=state.journal.map((r,i)=>importantRecord(r)?i:-1).filter(i=>i>=0),position=indexes.indexOf(index),older=indexes[position+1],newer=indexes[position-1];
 const point=state.rewindPoints?.find(p=>p.id===row.checkpointId),lesson=data.lessons.find(l=>l.id===row.card);
 return {title:row.title,body:`<p class="record-date">${monthLabel(row.month)} · ${typeLabel(row)}</p>${recordScene(state,data,row)}${row.choice?`<div class="record-choice"><span>그때의 선택</span><h3>${esc(row.choice)}</h3>${row.adviser?`<small>따른 조언 · ${esc(row.adviser)}</small>`:''}</div>`:''}<p class="record-outcome">${esc(row.text)}</p>${lesson?`<div class="record-lesson"><span>얻은 배움</span><h4>${esc(lesson.title)}</h4><p>${esc(lesson.body)}</p></div>`:''}<div class="record-replay">${state.mode==='custom'?'<p>커스텀 새 도전은 오늘의 무료 1회 또는 이용권 1장을 사용해요.</p>':''}${point?`<p>${point.type==='event'?'이 선택을 하기 전':'이 달의 일정을 진행하기 전'}으로 돌아가요. 기존 저장은 유지돼요. 새로 시작한 진행은 저장 버튼을 눌러 새 슬롯에 남겨 주세요.</p><button class="primary" data-action="history-replay" data-id="${esc(point.id)}">이 시점에서 다시 플레이</button>`:'<p>이 기록은 되돌릴 상태가 저장되어 있지 않아 열람만 가능해요. 업데이트 후 진행하는 월·사건부터 다시 플레이할 수 있어요.</p>'}</div><div class="record-navigation"><button class="quiet" data-action="history-record" data-index="${older}" ${older===undefined?'disabled':''}>이전 기록</button><button class="quiet" data-action="close">기록 목록으로</button><button class="quiet" data-action="history-record" data-index="${newer}" ${newer===undefined?'disabled':''}>다음 기록</button></div>`};
}
